  "hm.mh.cash": "books say cash {c}, bank {b}",
  "hm.mh.gst": "dates are on the GST calendar",
  "hm.me.note": "The ticks are yours: the App only shows facts from your records next to each step. They are saved with your data per business and month, so they travel with your backup.",
  "hm.h.need": "The health score needs at least 3 full months of bills and expenses before today. {n} months found so far.",
  "hm.h.score": "Score out of 100",
  "hm.h.good": "Healthy",
  "hm.h.ok": "Needs watching",
  "hm.h.low": "Needs attention",
  "hm.h.lead": "The average of the parts below, from {n} months of your records.",
  "hm.h.na": "not enough data",
  "hm.h.nodata": "There is not enough in your records to work this part out yet.",
  "hm.h.advice": "What to do:",
  "hm.h.how": "How this is worked out",
  "hm.h.chip": "Health {n}/100",
  "hm.h.note": "This is a rough guide from the bills and expenses you entered, not accounting or financial advice. Stock in hand and bills not entered are not counted; the margin is sales less purchases and expenses of the same months.",
  "hm.h.cash": "Cash cover",
  "hm.h.cash.how": "Cash and bank {c}. You spend about {b} a month on purchases and expenses, so the money covers {m} months.",
  "hm.h.cash.good": "Good cushion. Keep it, and keep next month's big payments in mind.",
  "hm.h.cash.ok": "A thin cushion. Collect overdue money and avoid big purchases for now.",
  "hm.h.cash.low": "Very little cash for what you spend. Collect dues first and delay what can wait.",
  "hm.h.cash.rule": "Cash and bank balance divided by the average monthly purchases and expenses of the last 3 full months. 2 months or more scores 100, nothing or less scores 0.",
  "hm.h.recv": "Receivable days",
  "hm.h.recv.how": "Customers owe {r}. You sell about {d} a day, so a bill takes about {n} days to come back.",
  "hm.h.recv.good": "Money comes back quickly. Keep reminding the slow ones.",
  "hm.h.recv.ok": "Money comes back slowly. Send reminders each week from the Dues screen.",
  "hm.h.recv.low": "Money is stuck with customers for too long. Chase the oldest bills first and ask for part payment before new orders.",
  "hm.h.recv.rule": "Money customers still owe divided by sales a day over the last 3 full months. 30 days or less scores 100, 90 days or more scores 0.",
  "hm.h.margin": "Margin",
  "hm.h.margin.how": "Of every 100 you sold in the last 3 months, {p} was left after purchases and expenses. The 3 months before that: {q}.",
  "hm.h.margin.how1": "Of every 100 you sold in the last 3 months, {p} was left after purchases and expenses.",
  "hm.h.margin.good": "A healthy share is left. Protect it when you change prices.",
  "hm.h.margin.ok": "The margin is thin or falling. Check your selling prices and the cost of your top items.",
  "hm.h.margin.low": "Almost nothing is left. Raise prices, cut costs or stop selling items that lose money.",
  "hm.h.margin.rule": "Sales less purchases and expenses, as a share of sales, for the last 3 full months. 15 or more scores 100, 0 or less scores 0; 20 points are taken off if it fell by more than 5 points against the 3 months before. Stock in hand is not counted.",
  "hm.h.creep": "Expense creep",
  "hm.h.creep.how": "Last month your expenses were {l}; the 3 months before averaged {a}. That is a change of {p}%.",
  "hm.h.creep.good": "Expenses are steady.",
  "hm.h.creep.ok": "Expenses are rising. Look at which head went up on the Reports screen.",
  "hm.h.creep.low": "Expenses jumped. Find the head that rose, and check it is not a one-time bill.",
  "hm.h.creep.rule": "Last full month's expenses against the average of the 3 months before it. Up 5% or less scores 100, up 40% or more scores 0. A one-time big bill will lower it for a month.",
  "hm.rm.t": "Reminders on this device",
  "hm.rm.p": "When you open the App it shows what needs you today. You can also let it show a phone notification for the most urgent lines, once a day each.",
  "hm.rm.on": "Show a notification when I open the App",
  "hm.rm.nosupport": "This browser does not support notifications. The list on My day still works.",
  "hm.rm.denied": "Notifications are blocked for this site. Allow them in the browser's site settings, then tick the box again.",
  "hm.rm.off": "Notifications are off.",
  "hm.rm.set": "Notifications are on. The most urgent lines will show when you open the App.",
  "hm.rm.title": "{b}: needs you today",
  "hm.rm.ics": "Put due dates in your phone's calendar",
  "hm.rm.icsp": "Makes a calendar file of the next 60 days: bill due dates and tax dates. Open it on your phone to add them to your own calendar, which rings a day before by itself, even when this App is closed.",
  "hm.rm.icsgo": "Make the calendar file",
  "hm.rm.icsnone": "No due dates in the next 60 days to put in a calendar.",
  "hm.rm.icsdone": "Calendar file made with {n} dates. Open it to add them.",
  "hm.rm.recv": "Collect",
  "hm.rm.pay": "Pay",
  "hm.rm.lim": "What a browser cannot do",
  "hm.rm.l1": "A web page cannot run when it is closed, and there is no server behind this App to send you a push message. So a reminder from the App appears only when you open the App.",
  "hm.rm.l2": "Everything is worked out on your device, so it works with no internet. Nothing about your business is sent anywhere.",
  "hm.rm.l3": "For dates you must not miss, use the calendar file: your phone's calendar rings by itself. It is a snapshot of today, so make a new file after you enter new bills.",
  "hm.rm.l4": "On an installed App the number on its icon shows how many urgent things there are, where your phone allows it.",
