  "it.b1": "ريٽ ({d} تي)، ٽيڪس سال 2026-27: نئون ريجيم ₹4 لک تائين صفر، ₹8 لک تائين 5%، ₹12 لک تائين 10%، ₹16 لک تائين 15%، ₹20 لک تائين 20%، ₹24 لک تائين 25%، ان کان مٿي 30%؛ ريبيٽ جنهن سان ₹12 لک تائين آمدني تي ٽيڪس ناهي، ان کان ٿورو مٿي مارجنل رليف سان؛ پگهار تي اسٽينڊرڊ ڊڊڪشن ₹75,000. پراڻو ريجيم: ₹2.5 لک تائين صفر (60 تي ₹3 لک، 80 تي ₹5 لک)، ₹5 لک تائين 5%، ₹10 لک تائين 20%، ان کان مٿي 30%؛ ₹5 لک تائين ريبيٽ ₹12,500؛ اسٽينڊرڊ ڊڊڪشن ₹50,000. اهي اهي ريٽ آهن جيڪي سيلري سلپ ٽول اڳ ۾ استعمال ڪري ٿو؛ هن بلڊ ۾ Finance Act مان ٻيهر نه پڙهيا ويا، تنهنڪري چيڪ ڪريو.",
