  "it.b3": "سود: سيڪشن 424 (پراڻو 234B) ڪمي تي هر مهيني يا مهيني جي حصي تي 1% آهي جڏهن ٽيڪس جو 90% کان گهٽ ڏنو ويو؛ سيڪشن 425 (پراڻو 234C) پهرين ٽن قسطن مان هر هڪ جي ڪمي تي 3% (جيڪڏهن 15 June تائين 12% ۽ 15 September تائين 36% ڏنو ته ڪجهه نه) ۽ March جي ڪمي تي 1% آهي.",
