  "ca.intro": "هڪ بزنس ۽ عرصي کي هڪ رڳو پڙهڻ واري فائل (.nsca) ۾ پيڪ ڪري ٿو. اها پنهنجي اڪائونٽنٽ کي WhatsApp يا اي ميل سان موڪليو. اهي ان کي ca.niveshsahayak.in تي کولين ٿا، کاتا پڙهن ٿا، سوال شامل ڪن ٿا ۽ تبصرا توهان ڏانهن واپس موڪلين ٿا.",
  "ca.notlive": "هي فائل جي حوالگي آهي، لائيو گڏيل لاگ ان ناهي. توهان جو اڪائونٽنٽ کاتا اهڙا ڏسي ٿو جهڙا فائل ٺاهڻ وقت هئا. لائيو لاگ ان لاءِ اهڙو سرور گهرجي جيڪو توهان جا کاتا رکي، ۽ Nivesh Sahayak وٽ ڪو سرور ناهي: توهان جا کاتا توهان جي ڊوائيس تي رهن ٿا. نين انٽرين لاءِ نئين فائل ٺاهيو.",
  "ca.what": "ڇا شامل ٿئي ٿو",
  "ca.earlier": "پهرين تاريخ کان اڳ جون انٽريون به (اوپننگ بيلنس ۽ ايجنگ لاءِ گهرجن)",
