  "ca.extrah": "ٽڪ ڪرڻ کان سواءِ شامل ناهي. تصويرون (لوگو، صحيح)، توهان جو PIN ۽ بيڪ اپ سيٽنگون ڪڏهن به شامل ناهن ٿينديون.",
