  "ca.general": "عام تبصرو",
  "cv.h1": "اڪائونٽنٽ ويوئر: پنهنجي ڪلائنٽ جي موڪليل کاتن واري فائل کوليو",
  "cv.intro": "توهان جو ڪلائنٽ هڪ عرصي جا کاتا هڪ فائل ۾ پيڪ ڪري توهان کي WhatsApp يا اي ميل تي موڪلي ٿو. ان کي هتي کولي پڙهو: بقايا، پارٽيون، ليجر، ڊي بڪ، GST حساب، فائنل اڪائونٽس ۽ هر ڊاڪيومينٽ. ڳوليو ۽ فلٽر ڪريو، ڪنهن به انٽري تي سوال ڪريو، ۽ پنهنجا تبصرا ننڍي فائل طور واپس موڪليو. مفت، لاگ ان کان سواءِ، ۽ ڪجهه به اپلوڊ ناهي ٿيندو: فائل توهان جي برائوزر اندر پڙهي وڃي ٿي.",
