  "cv.cT": "سوال ۽ تبصرا",
  "cv.how.h": "هي ڪيئن ڪم ڪري ٿو",
  "cv.how.1": "توهان جو ڪلائنٽ Nivesh Sahayak کولي، منهنجو ڊيٽا ۾ وڃي، پنهنجي اڪائونٽنٽ کي موڪليو ۾ هڪ بزنس ۽ عرصي لاءِ \"منهنجي اڪائونٽنٽ لاءِ فائل ٺاهيو\" چونڊي ٿو.",
  "cv.how.2": "اهي توهان کي فائل (جنهن جي آخر ۾ .nsca) ۽ ساڳئي پيغام ۾ هڪ ننڍو چيڪ ڪوڊ موڪلين ٿا.",
  "cv.how.3": "توهان فائل هن پيج تي کوليو ٿا. پيج ٻڌائي ٿو ته فائل بدليل ناهي، ۽ ڪلائنٽ جو ڏنل چيڪ ڪوڊ لکي ملائڻ ڏئي ٿو.",
  "cv.how.4": "کاتا پڙهو، ڳوليو، ۽ ڪنهن به ڊاڪيومينٽ، ڊي بڪ انٽري يا اسڪرين تي \"سوال يا تبصرو شامل ڪريو\" دٻايو. جيڪو لکو اهو هن برائوزر ۾ رهي ٿو.",
  "cv.how.5": "جڏهن ختم ڪريو، \"سوال ۽ تبصرا\" کولي ننڍي .nsca-comments فائل واپس موڪليو. توهان جو ڪلائنٽ ان کي لوڊ ڪري هر سوال انٽري سان گڏ ڏسي ٿو. اهي جواب ڏئي سگهن ٿا، ۽ توهان جواب هتي لوڊ ڪري سگهو ٿا.",
  "cv.live.h": "فائل جي حوالگي، لائيو لاگ ان ناهي",
  "cv.live.p": "هي فائل جي حوالگي آهي. توهان پنهنجي ڪلائنٽ جي اڪائونٽ ۾ لاگ ان نٿا ٿيو ۽ بعد ۾ ٿيل تبديليون نٿا ڏسو. لائيو گڏيل لاگ ان لاءِ اهڙو سرور گهرجي جيڪو کاتا رکي، ۽ Nivesh Sahayak وٽ ڪو سرور ناهي: کاتا توهان جي ڪلائنٽ جي ڊوائيس تي رهن ٿا. نئين عرصي لاءِ يا درستين کان پوءِ پنهنجي ڪلائنٽ کان نئين فائل گهرو.",
  "cv.safe.h": "فائل ۾ ڇا آهي، ۽ ڇا ناهي",
  "cv.safe.p": "توهان جو ڪلائنٽ ٽڪ ڪري ٿو ته ڇا شامل ٿئي. عام طور فائل ۾ هڪ بزنس جون انٽريون، پارٽيون ۽ آئٽم عرصي جي آخر تائين هوندا آهن. ڪوٽيشن ۽ آرڊر، پگهار ۽ اسٽاف جا رڪارڊ، فون نمبر ۽ اي ميل پتا، ۽ بزنس جي بئنڪ اڪائونٽ جي تفصيل تيستائين شامل ناهن جيستائين ڪلائنٽ ٽڪ نه ڪري. تصويرون، PIN ۽ بيڪ اپ سيٽنگون ڪڏهن به شامل ناهن. فائل ۾ چيڪ سم آهي تنهنڪري ان ۾ ڪا به تبديلي هن پيج تي ظاهر ٿئي ٿي. چيڪ سم ان ماڻهوءَ کي نٿو روڪي سگهي جيڪو فائل بدلائي ٻيهر ڳڻي، تنهنڪري چيڪ ڪوڊ ان ڪوڊ سان ملايو جيڪو توهان جي ڪلائنٽ الڳ موڪليو.",
  "cv.readonly": "هي فائل جو رڳو پڙهڻ وارو ڏيک آهي: هتي ڪجهه به بدلائي يا سيو ڪري نٿو سگهجي.",
