  "hm.h.creep.rule": "گذريل پوري مهيني جا خرچ ان کان اڳ 3 مهينن جي اوسط سان. 5% يا گهٽ واڌ = 100، 40% يا وڌيڪ واڌ = 0. هڪ ڀيري جو وڏو بل هڪ مهيني لاءِ ان کي گهٽائيندو.",
  "hm.rm.t": "هن ڊوائيس تي يادگيريون",
  "hm.rm.p": "جڏهن توهان ايپ کوليو ٿا ته اها ڏيکاري ٿي ته اڄ ڇا توهان جو ڌيان گهري ٿو. سڀ کان ضروري لائينن لاءِ، هر هڪ لاءِ ڏينهن ۾ هڪ ڀيرو، فون نوٽيفڪيشن به ڏيکاري سگهي ٿي.",
  "hm.rm.on": "ايپ کولڻ تي نوٽيفڪيشن ڏيکاريو",
  "hm.rm.nosupport": "هي برائوزر نوٽيفڪيشن کي سپورٽ نٿو ڪري. منهنجو ڏينهن واري لسٽ تڏهن به ڪم ڪري ٿي.",
  "hm.rm.denied": "هن سائيٽ لاءِ نوٽيفڪيشن بند آهن. برائوزر جي سائيٽ سيٽنگن ۾ اجازت ڏيو، پوءِ باڪس ٻيهر ٽڪ ڪريو.",
  "hm.rm.off": "نوٽيفڪيشن بند آهن.",
  "hm.rm.set": "نوٽيفڪيشن چالو آهن. سڀ کان ضروري لائينون ايپ کولڻ تي ڏيکاريون وينديون.",
  "hm.rm.title": "{b}: اڄ توهان جو ڌيان گهرجي",
  "hm.rm.ics": "ڏيڻ جون تاريخون فون جي ڪئلينڊر ۾ وجهو",
  "hm.rm.icsp": "ايندڙ 60 ڏينهن جي ڪئلينڊر فائل ٺاهي ٿو: بلن جون ڏيڻ جون تاريخون ۽ ٽيڪس جون تاريخون. انهن کي پنهنجي ڪئلينڊر ۾ شامل ڪرڻ لاءِ فون تي کوليو، جيڪو هڪ ڏينهن اڳ پاڻ ئي وڄندو، تڏهن به جڏهن هي ايپ بند هجي.",
  "hm.rm.icsgo": "ڪئلينڊر فائل ٺاهيو",
  "hm.rm.icsnone": "ايندڙ 60 ڏينهن ۾ ڪئلينڊر ۾ وجهڻ لاءِ ڪا ڏيڻ جي تاريخ ناهي.",
  "hm.rm.icsdone": "{n} تاريخن سان ڪئلينڊر فائل ٺهي. انهن کي شامل ڪرڻ لاءِ کوليو.",
  "hm.rm.recv": "وصول ڪريو",
  "hm.rm.pay": "ڏيو",
  "hm.rm.lim": "برائوزر ڇا نٿو ڪري سگهي",
  "hm.rm.l1": "ويب پيج بند هجڻ وقت نٿو هلي سگهي، ۽ هن ايپ پويان ڪو سرور ناهي جيڪو توهان کي پش پيغام موڪلي. تنهنڪري ايپ جي يادگيري رڳو تڏهن ظاهر ٿئي ٿي جڏهن ايپ کوليو.",
  "hm.rm.l2": "سڀ ڪجهه توهان جي ڊوائيس تي ڳڻيو وڃي ٿو، تنهنڪري انٽرنيٽ کان سواءِ ڪم ڪري ٿو. توهان جي بزنس بابت ڪجهه به ڪٿي نٿو موڪليو وڃي.",
  "hm.rm.l3": "جيڪي تاريخون وسارڻ نه گهرجن انهن لاءِ ڪئلينڊر فائل استعمال ڪريو: توهان جي فون جو ڪئلينڊر پاڻ وڄي ٿو. هي اڄ جي تصوير آهي، تنهنڪري نوان بل لکڻ کان پوءِ نئين فائل ٺاهيو.",
  "hm.rm.l4": "انسٽال ٿيل ايپ تي ان جي آئڪن تي انگ ڏيکاري ٿو ته ڪيترا ضروري ڪم آهن، جتي توهان جو فون اجازت ڏئي.",
